using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RemainingCores {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/",P="Assets/Afrer_Seconds/05.Model/Props/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Transform root,group;
 static GameObject Child(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static GameObject Model(string n,Transform p,bool collide){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(E+n+".fbx"),p);g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;g.transform.localScale=Vector3.one;g.name=n;if(collide)foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;return g;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;group=root.Find("Remaining_Domes_Art");if(group.Find("VB"))throw new Exception("Already applied");foreach(string n in new[]{"RD_VB_Shaft","RD_VL_Shaft","RD_VL_Hoist","RD_VL_Floor"}){var path=E+n+".fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Materials"),"RD_*.mat")){var m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+Path.GetFileName(f));mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),m.name),m);}mi.SaveAndReimport();}
 foreach(string code in new[]{"VB","VL"}){var room=Child(code,group).transform;room.position=new Vector3(44,-82,code=="VB"?-28:28);Model("RD_"+code+"_Shaft",room,true);var original=root.Find("B5_FullLayout_Implementation/AF_B5_FullLayout/CF_B5_"+code+"_Dome.001");original.GetComponent<Renderer>().enabled=false;foreach(var col in original.GetComponents<Collider>())col.enabled=false;
 if(code=="VB"){foreach(string n in new[]{"Stairs","Railings","Services","SafetyEquipment","Lighting","UpperDoor","Floor"})Model("TA_VA_"+n,room,new[]{"Stairs","Railings","UpperDoor","SafetyEquipment"}.Contains(n));foreach(float x in new[]{-1.76f,1.76f})foreach(float z in new[]{-3.08f,3.08f}){var col=Child("Column_Collision",room).AddComponent<BoxCollider>();col.center=new Vector3(x,8,z);col.size=new Vector3(.14f,16,.14f);}int i=0;foreach(float y in new[]{5.2f,9.2f,13.2f,17.2f})foreach(float x in new[]{-3.82f,3.82f}){var g=Child("Upper_Landing_Light_"+i++,room);g.transform.localPosition=new Vector3(x,y,0);var l=g.AddComponent<Light>();l.type=LightType.Point;l.color=new Color(.8f,.9f,1);l.intensity=2.6f;l.range=6.2f;l.shadows=LightShadows.Soft;l.shadowStrength=.8f;}
 foreach(var t in root.Find("Lighting").Cast<Transform>().Where(t=>t.name.StartsWith("VB_Work_"))){if(t.name.EndsWith("_1"))t.position=new Vector3(44,-78.8f,-32.5f);if(t.name.EndsWith("_3"))t.position=new Vector3(44,-78.8f,-23.5f);}}
 else{Model("RD_VL_Hoist",room,true);Model("RD_VL_Floor",room,false);}}
 // Fork the latest VA-cleaned collar mesh and remove only the two replaced spherical core collars.
 var reports=new List<object>();foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>AssetDatabase.GetAssetPath(f.sharedMesh).EndsWith("TA_PortalCollars_VAReplaced.asset"))){var src=mf.sharedMesh;var vs=src.vertices;var m=UnityEngine.Object.Instantiate(src);m.name="RD_PortalCollars_VerticalCores";int removed=0;for(int sub=0;sub<m.subMeshCount;sub++){var ts=src.GetTriangles(sub);var keep=new List<int>();for(int i=0;i<ts.Length;i+=3){var p=(mf.transform.TransformPoint(vs[ts[i]])+mf.transform.TransformPoint(vs[ts[i+1]])+mf.transform.TransformPoint(vs[ts[i+2]]))/3;bool cut=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(44,-28))<7||Vector2.Distance(new Vector2(p.x,p.z),new Vector2(44,28))<7;if(cut)removed++;else keep.AddRange(new[]{ts[i],ts[i+1],ts[i+2]});}m.SetTriangles(keep,sub);}m.RecalculateBounds();AssetDatabase.CreateAsset(m,E+m.name+".asset");mf.sharedMesh=m;foreach(var c in mf.GetComponents<MeshCollider>())if(c.sharedMesh==src)c.sharedMesh=m;reports.Add(new{removed,retained=m.triangles.Length/3});}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{cores=2,VBsteps=96,rise=16,liftStatic=true,newLights=8,collars=reports};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/cores.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
